// Lookup: floorId -> building + floor info
export const FLOOR_LOOKUP = Object.fromEntries(
  BUILDINGS.flatMap(b =>
    b.floors.map(f => [f.floorId, { ...f, buildingId: b.id, buildingName: b.name }])
  )
);

// Lookup: buildingId -> building
export const BUILDING_LOOKUP = Object.fromEntries(
  BUILDINGS.map(b => [b.id, b])
);
